#!/usr/bin/env bash
# scripts/deploy.sh
# Interactive scenario deployment menu
# Usage: ./scripts/deploy.sh [scenario_name]
# Generated by: INFRA_AGENT during /phase 5
# Updated: see CHANGELOG.md

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
SCENARIOS_DIR="${REPO_ROOT}/terraform/scenarios"
DOCS_DIR="${REPO_ROOT}/docs/scenarios"

# ── Color codes ──────────────────────────────────────────────────────────────
RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[1;33m'
CYAN='\033[0;36m'; BOLD='\033[1m'; RESET='\033[0m'

# ── Prereq checks ────────────────────────────────────────────────────────────
for cmd in terraform jq; do
  if ! command -v "$cmd" &>/dev/null; then
    echo -e "${RED}❌ Required command not found: $cmd${RESET}"
    exit 1
  fi
done

if [[ -z "${PROXMOX_VE_API_TOKEN_ID:-}" || -z "${PROXMOX_VE_API_TOKEN_SECRET:-}" ]]; then
  echo -e "${YELLOW}⚠️  Proxmox credentials not set. Run: source scripts/lab-env.local.sh${RESET}"
  exit 1
fi

# ── Discover scenarios ───────────────────────────────────────────────────────
mapfile -t SCENARIO_DIRS < <(find "${SCENARIOS_DIR}" -maxdepth 1 -mindepth 1 -type d | sort)

if [[ ${#SCENARIO_DIRS[@]} -eq 0 ]]; then
  echo -e "${YELLOW}No scenarios found in ${SCENARIOS_DIR}${RESET}"
  echo "Run /phase 8 in Claude Code to build the initial scenario catalog."
  exit 1
fi

# ── Menu ─────────────────────────────────────────────────────────────────────
print_header() {
  echo ""
  echo -e "${CYAN}╔═══════════════════════════════════════════════════════════╗${RESET}"
  echo -e "${CYAN}║               VULNERABILITY LAB DEPLOYMENT                ║${RESET}"
  echo -e "${CYAN}╚═══════════════════════════════════════════════════════════╝${RESET}"
  echo ""
}

print_header

# If scenario passed as argument, skip menu
if [[ $# -gt 0 ]]; then
  SELECTED_SCENARIO="$1"
else
  echo -e "${BOLD}Available scenarios:${RESET}"
  echo ""
  for i in "${!SCENARIO_DIRS[@]}"; do
    SCENARIO_NAME=$(basename "${SCENARIO_DIRS[$i]}")
    YAML_FILE="${SCENARIO_DIRS[$i]}/scenario.yaml"
    if [[ -f "$YAML_FILE" ]]; then
      DIFFICULTY=$(grep 'difficulty:' "$YAML_FILE" | awk '{print $2}' 2>/dev/null || echo "Unknown")
      DURATION=$(grep 'estimated_hours:' "$YAML_FILE" | awk '{print $2}' 2>/dev/null || echo "?")
      echo -e "  ${CYAN}[$((i+1))]${RESET} ${BOLD}${SCENARIO_NAME}${RESET}"
      echo -e "       Difficulty: ${DIFFICULTY}  Duration: ~${DURATION}h"
    else
      echo -e "  ${CYAN}[$((i+1))]${RESET} ${BOLD}${SCENARIO_NAME}${RESET}"
    fi
    echo ""
  done

  echo -n "Select scenario [1-${#SCENARIO_DIRS[@]}]: "
  read -r SELECTION

  if ! [[ "$SELECTION" =~ ^[0-9]+$ ]] || \
     [[ "$SELECTION" -lt 1 ]] || \
     [[ "$SELECTION" -gt ${#SCENARIO_DIRS[@]} ]]; then
    echo -e "${RED}Invalid selection${RESET}"; exit 1
  fi

  SELECTED_SCENARIO=$(basename "${SCENARIO_DIRS[$((SELECTION-1))]}")
fi

SCENARIO_DIR="${SCENARIOS_DIR}/${SELECTED_SCENARIO}"

if [[ ! -d "$SCENARIO_DIR" ]]; then
  echo -e "${RED}❌ Scenario not found: ${SELECTED_SCENARIO}${RESET}"; exit 1
fi

# ── Deploy ───────────────────────────────────────────────────────────────────
echo ""
echo -e "${BOLD}Deploying: ${GREEN}${SELECTED_SCENARIO}${RESET}"
echo -e "Directory: ${SCENARIO_DIR}"
echo ""

cd "${SCENARIO_DIR}"

# Create or select Terraform workspace
terraform workspace new "${SELECTED_SCENARIO}" 2>/dev/null || \
  terraform workspace select "${SELECTED_SCENARIO}"

echo -e "${CYAN}→ Running terraform init...${RESET}"
terraform init -input=false

echo -e "${CYAN}→ Running terraform plan...${RESET}"
terraform plan -var-file=terraform.tfvars -input=false -out=tfplan

echo ""
echo -e "${YELLOW}Review the plan above. Proceed with deployment? [y/N]${RESET}"
read -r CONFIRM
if [[ "${CONFIRM,,}" != "y" ]]; then
  echo "Deployment cancelled."; rm -f tfplan; exit 0
fi

echo -e "${CYAN}→ Applying...${RESET}"
terraform apply tfplan
rm -f tfplan

# ── Print access sheet ───────────────────────────────────────────────────────
echo ""
echo -e "${GREEN}╔═══════════════════════════════════════════════════════════╗${RESET}"
echo -e "${GREEN}║                   STUDENT ACCESS SHEET                    ║${RESET}"
echo -e "${GREEN}╚═══════════════════════════════════════════════════════════╝${RESET}"
echo ""

ACCESS=$(terraform output -json access_sheet 2>/dev/null || echo "{}")
if [[ "$ACCESS" != "{}" ]]; then
  echo "$ACCESS" | jq -r 'to_entries[] | "  \(.key): \(.value)"'
else
  echo "  Scenario: ${SELECTED_SCENARIO}"
  echo "  See: ${DOCS_DIR}/${SELECTED_SCENARIO}/SCENARIO_CARD.md for credentials"
fi

echo ""
echo -e "  ${CYAN}Objectives: ${DOCS_DIR}/${SELECTED_SCENARIO}/OBJECTIVES.md${RESET}"
echo ""
echo -e "${GREEN}✅ Scenario deployed successfully${RESET}"
echo ""
